<div class="mw-heading mw-heading2"><h2 id="Update_history">Update history</h2><span class="mw-editsection"><span class="mw-editsection-bracket">[</span><a href="/w/Nex?section=35&amp;veaction=edit" title="Edit section: Update history" class="mw-editsection-visualeditor"><span>edit</span></a><span class="mw-editsection-divider"> | </span><a href="/w/Nex?action=edit&amp;section=35" title="Edit section&#039;s source code: Update history"><span>edit source</span></a><span class="mw-editsection-bracket">]</span></span></div>
